function Get-MediaForgeIconPath {
    try {
        $local = Join-Path $PSScriptRoot 'mediaforge.ico'
        if (Test-Path -LiteralPath $local) { return $local }
        $tmp = Join-Path $env:TEMP 'mediaforge.ico'
        [System.IO.File]::WriteAllBytes($tmp, [Convert]::FromBase64String($script:EmbeddedMediaForgeIconBase64))
        return $tmp
    } catch { return $null }
}
function Get-MediaForgeHeaderImage {
    try {
        $bytes = [Convert]::FromBase64String($script:EmbeddedMediaForgePngBase64)
        $ms = New-Object System.IO.MemoryStream(,$bytes)
        return [System.Drawing.Image]::FromStream($ms)
    } catch { return $null }
}
