function Get-MediaForgeIconPath {
    try {
        $iconCandidates = @(
            (Join-Path $PSScriptRoot 'mediaforge.ico'),
            (Join-Path $PSScriptRoot 'MediaForge.ico'),
            (Join-Path (Split-Path -Parent $PSCommandPath) 'mediaforge.ico'),
            (Join-Path $env:TEMP 'mediaforge.ico')
        ) | Select-Object -Unique

        foreach ($iconPath in $iconCandidates) {
            if ($iconPath -and (Test-Path -LiteralPath $iconPath)) { return $iconPath }
        }

        $fallback = Join-Path $env:TEMP 'mediaforge.ico'
        [System.IO.File]::WriteAllBytes($fallback, [Convert]::FromBase64String($script:EmbeddedMediaForgeIconBase64))
        return $fallback
    } catch {
        return $null
    }
}

function Get-MediaForgeHeaderImage {
    try {
        $bytes = [Convert]::FromBase64String($script:EmbeddedMediaForgePngBase64)
        $ms = New-Object System.IO.MemoryStream(,$bytes)
        return [System.Drawing.Image]::FromStream($ms)
    } catch {
        return $null
    }
}

function Set-AppIcon {
    try {
        $iconPath = Get-MediaForgeIconPath
        if ($iconPath -and (Test-Path -LiteralPath $iconPath)) {
            $script:AppIconPath = $iconPath
            $form.Icon = New-Object System.Drawing.Icon($iconPath)
        }
    } catch { }
}

