$script:MFThemeRefs = New-Object System.Collections.Generic.List[string]

function Add-MFThemeRef {
    param($PathOrAssembly)

    try {
        if ($null -eq $PathOrAssembly) { return }

        $path = $null
        if ($PathOrAssembly -is [System.Reflection.Assembly]) {
            $path = $PathOrAssembly.Location
        } else {
            $path = [string]$PathOrAssembly
        }

        if ([string]::IsNullOrWhiteSpace($path)) { return }
        if (-not (Test-Path -LiteralPath $path)) { return }
        if (-not $script:MFThemeRefs.Contains($path)) {
            [void]$script:MFThemeRefs.Add($path)
        }
    } catch { }
}

# PowerShell 7 / .NET needs the forwarded assemblies explicitly when compiling
# custom WinForms controls with Add-Type.  Without these, pwsh 7.6+ throws
# missing-reference errors for System.ComponentModel.Primitives,
# System.Drawing.Primitives, and System.Drawing.Common.
try {
    $tpa = [AppContext]::GetData('TRUSTED_PLATFORM_ASSEMBLIES')
    if ($tpa) {
        foreach ($asmPath in ($tpa -split [IO.Path]::PathSeparator)) {
            $leaf = [IO.Path]::GetFileName($asmPath)
            if ($leaf -in @(
                'System.Private.CoreLib.dll',
                'System.Runtime.dll',
                'System.Runtime.Extensions.dll',
                'System.Collections.dll',
                'System.ObjectModel.dll',
                'System.ComponentModel.dll',
                'System.ComponentModel.Primitives.dll',
                'System.ComponentModel.TypeConverter.dll',
                'System.Drawing.dll',
                'System.Drawing.Common.dll',
                'System.Drawing.Primitives.dll',
                'System.Windows.Forms.dll',
                'System.Windows.Forms.Primitives.dll',
                'System.Private.Windows.Core.dll',
                'Microsoft.Win32.SystemEvents.dll'
            )) {
                Add-MFThemeRef $asmPath
            }
        }
    }
} catch { }

try { Add-MFThemeRef ([System.Windows.Forms.Form].Assembly) } catch { }
try { Add-MFThemeRef ([System.Windows.Forms.Button].Assembly) } catch { }
try { Add-MFThemeRef ([System.Drawing.Bitmap].Assembly) } catch { }
try { Add-MFThemeRef ([System.Drawing.Graphics].Assembly) } catch { }
try { Add-MFThemeRef ([System.Drawing.Drawing2D.GraphicsPath].Assembly) } catch { }
try { Add-MFThemeRef ([System.Drawing.Rectangle].Assembly) } catch { }
try { Add-MFThemeRef ([System.Drawing.Color].Assembly) } catch { }
try { Add-MFThemeRef ([System.ComponentModel.Component].Assembly) } catch { }
try { Add-MFThemeRef ([System.ComponentModel.TypeConverter].Assembly) } catch { }

if ($script:MFThemeRefs.Count -eq 0) {
