        using(Pen pen=new Pen(Color.FromArgb(52,66,84),1.2f)) g.DrawPath(pen,p);
        using(Pen hi=new Pen(Color.FromArgb(28,255,255,255),1f)) g.DrawLine(hi, 12, 5, Math.Max(12,Width-14), 5);
      }
    }
  }

  public class GlassButton : Button {
    public string Kind { get; set; } = "soft";
    public int Radius { get; set; } = 16;
    public GlassButton() {
      this.SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.UserPaint | ControlStyles.ResizeRedraw, true);
      this.FlatStyle = FlatStyle.Flat; this.FlatAppearance.BorderSize = 0; this.BackColor = Color.Transparent;
      this.ForeColor = Color.FromArgb(238,242,247); this.Cursor = Cursors.Hand;
    }
    protected GraphicsPath Round(Rectangle r, int rad) {
      int d=rad*2; GraphicsPath p=new GraphicsPath();
      p.AddArc(r.X,r.Y,d,d,180,90); p.AddArc(r.Right-d,r.Y,d,d,270,90);
      p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90); p.AddArc(r.X,r.Bottom-d,d,d,90,90);
      p.CloseFigure(); return p;
    }
    protected override void OnPaint(PaintEventArgs e) {
      Graphics g=e.Graphics; g.SmoothingMode=SmoothingMode.AntiAlias;
      Rectangle r=new Rectangle(1,1,Width-3,Height-3);
      bool over=ClientRectangle.Contains(PointToClient(Cursor.Position));
      bool down=Capture && (Control.MouseButtons & MouseButtons.Left)==MouseButtons.Left;
      Color top=Color.FromArgb(over?48:34, over?55:39, over?66:48);
      Color bot=Color.FromArgb(10,12,16); Color border=Color.FromArgb(over?126:82, over?142:94, over?164:110);
      Color glow=Color.FromArgb(0,0,0,0); Color txt=Enabled?Color.FromArgb(238,242,247):Color.FromArgb(90,96,106);
      if(!Enabled){ top=Color.FromArgb(20,22,27); bot=Color.FromArgb(8,9,11); border=Color.FromArgb(42,46,52); }
      else if(Kind=="primary"){ top=Color.FromArgb(over?74:56, over?86:66, over?104:82); bot=Color.FromArgb(14,17,24); border=Color.FromArgb(214,232,250); glow=Color.FromArgb(95,190,225,255); }
      else if(Kind=="danger"){ top=Color.FromArgb(over?42:29, over?36:31, over?44:38); bot=Color.FromArgb(9,11,15); border=Color.FromArgb(over?158:76, over?82:80, over?96:92); txt=Enabled?Color.FromArgb(205,210,218):txt; }
      else if(Kind=="badge"){ top=Color.FromArgb(28,32,39); bot=Color.FromArgb(8,10,14); border=Color.FromArgb(56,70,88); }
      if(down){ top=Color.FromArgb(12,14,18); bot=Color.FromArgb(30,36,44); }
      using(GraphicsPath p=Round(r,Radius)){
        using(LinearGradientBrush b=new LinearGradientBrush(r,top,bot,90f)) g.FillPath(b,p);
