function Replace-MFPanelRef { param([ref]$Ref)
    $old=$Ref.Value; if(-not $old){ return }
    $new=New-Object MediaForgeTheme161.GlassPanel
    $new.Location=$old.Location; $new.Size=$old.Size; $new.Anchor=$old.Anchor; $new.Visible=$old.Visible
    $form.Controls.Remove($old); $form.Controls.Add($new); $new.SendToBack(); $Ref.Value=$new
}
function Replace-MFButtonRef { param([ref]$Ref,[string]$Text,[string]$Kind='soft',[int]$FontSize=10,[int]$Radius=16)
    $old=$Ref.Value; if(-not $old){ return }
    $new=New-Object MediaForgeTheme161.GlassButton
    $new.Text=$Text; $new.Kind=$Kind; $new.Radius=$Radius; $new.Location=$old.Location; $new.Size=$old.Size; $new.Anchor=$old.Anchor; $new.Enabled=$old.Enabled; $new.Visible=$old.Visible; $new.TabIndex=$old.TabIndex
    $new.Font=New-Object System.Drawing.Font('Segoe UI',$FontSize,$(if($Kind -eq 'primary'){[System.Drawing.FontStyle]::Bold}else{[System.Drawing.FontStyle]::Regular}))
    $form.Controls.Remove($old); $form.Controls.Add($new); $new.BringToFront(); $Ref.Value=$new
}
function Replace-MFRadioRef { param([ref]$Ref,[string]$Text)
    $old=$Ref.Value; if(-not $old){ return }
    $new=New-Object MediaForgeTheme161.GlassRadioButton
    $new.Text=$Text; $new.Checked=$old.Checked; $new.SelectedVisual=$old.Checked; $new.Location=$old.Location; $new.Size=$old.Size; $new.Anchor=$old.Anchor; $new.Enabled=$old.Enabled; $new.Visible=$old.Visible; $new.TabIndex=$old.TabIndex
    $new.Font=New-Object System.Drawing.Font('Segoe UI',11,[System.Drawing.FontStyle]::Regular)
    $form.Controls.Remove($old); $form.Controls.Add($new); $new.BringToFront(); $Ref.Value=$new
}
function Replace-MFBadgeRef { param([string]$Key)
    if(-not $script:EngineBadges -or -not $script:EngineBadges.ContainsKey($Key)){ return }
    $old=$script:EngineBadges[$Key]
    $new=New-Object MediaForgeTheme161.GlassButton
    $new.Text=('●  {0}    OK' -f $Key); $new.Kind='badge'; $new.Radius=18; $new.Location=$old.Location; $new.Size=$old.Size; $new.Anchor=$old.Anchor; $new.Enabled=$true; $new.Visible=$old.Visible
    $new.Font=New-Object System.Drawing.Font('Segoe UI',9.25,[System.Drawing.FontStyle]::Bold)
    $form.Controls.Remove($old); $form.Controls.Add($new); $new.BringToFront(); $script:EngineBadges[$Key]=$new
}
function Set-MFInput { param($Ctl)
    if(-not $Ctl){ return }
    try{ $Ctl.BackColor=[System.Drawing.Color]::FromArgb(8,11,15); $Ctl.ForeColor=[System.Drawing.Color]::FromArgb(230,236,244); $Ctl.Font=New-Object System.Drawing.Font('Segoe UI',10); if($Ctl -is [System.Windows.Forms.ComboBox]){$Ctl.FlatStyle='Flat'} }catch{}
}
function Enable-MFDoubleBuffer {
    param($Control)
    if (-not $Control) { return }
    try {
        $prop = [System.Windows.Forms.Control].GetProperty('DoubleBuffered', [System.Reflection.BindingFlags]'NonPublic,Instance')
        if ($prop) { $prop.SetValue($Control, $true, $null) }
    } catch { }
}

function Enable-MFFlickerSafePainting {
    param($Root)
    try {
        Enable-MFDoubleBuffer $Root
        if ($Root -and $Root.Controls) {
            foreach ($ctl in $Root.Controls) {
                Enable-MFDoubleBuffer $ctl
                try {
                    if ($ctl.Controls -and $ctl.Controls.Count -gt 0) {
                        foreach ($child in $ctl.Controls) { Enable-MFDoubleBuffer $child }
                    }
                } catch { }
            }
        }
    } catch { }
}

