    $rs=[runspacefactory]::CreateRunspace(); $rs.ApartmentState='MTA'; $rs.Open()
    $rs.SessionStateProxy.SetVariable('MinfoPath',   $MinfoPath)
    $rs.SessionStateProxy.SetVariable('Target',      $Target)
    $rs.SessionStateProxy.SetVariable('ImdbId',      $imdbId)
    $rs.SessionStateProxy.SetVariable('MovieTitle',  $movieTitle)
    $rs.SessionStateProxy.SetVariable('MovieYear',   $movieYear)
    $ps=[powershell]::Create(); $ps.Runspace=$rs
    [void]$ps.AddScript({
        Write-Host 'engine: minfocreate (MediaInfo + OMDb -> NFO/HTML/poster)'
        # Runspace has no console, so force minfocreate into plain-output mode
        # with both the switch and environment flags. The env flags protect us
        # even if PowerShell parameter binding is changed later.
        try {
            $env:MEDIAFORGE_GUI='1'
            $env:MEDIAFORGE_NONINTERACTIVE='1'
            $minfoArgs = @(
                '-VideoFile', $Target,
                '-Mode',      'single',
                '-NonInteractive'
            )

            # Do not pass the OMDb key as a command-line argument from the GUI.
            # minfocreate.ps1 owns minforc.ps1 loading and uses the same config
            # path as imdbthumbgrab.ps1. Keeping the key inside minfocreate
            # avoids argument-shift/binding bugs and keeps the GUI log cleaner.

            # MediaForge is an explicit metadata caller: when the user enters an
            # IMDb ID or title/year, Minfo must fetch OMDb data or fail loudly.
            # Do not silently create a "No OMDb data" HTML page from the GUI.
            $hasExplicitMovieMetadata = $false
            if ($ImdbId -and $ImdbId.Trim() -match 'tt\d{6,10}') {
                $cleanImdb = ([regex]::Match($ImdbId.Trim(), 'tt\d{6,10}', 'IgnoreCase')).Value.ToLowerInvariant()
                $minfoArgs += @('-ImdbId', $cleanImdb)
                $hasExplicitMovieMetadata = $true
            }
            if ($MovieTitle -and $MovieTitle.Trim()) {
                $minfoArgs += @('-SearchTitle', $MovieTitle.Trim())
                $hasExplicitMovieMetadata = $true
                if ($MovieYear -match '^\d{4}$') { $minfoArgs += @('-SearchYear', $MovieYear.Trim()) }
            }
            if ($hasExplicitMovieMetadata) {
                $minfoArgs += '-RequireOmdb'
            }

            $displayArgs = New-Object System.Collections.Generic.List[string]
            $hideNext = $false
            foreach ($arg in $minfoArgs) {
                if ($hideNext) {
                    $displayArgs.Add('<hidden>') | Out-Null
                    $hideNext = $false
                    continue
                }
                $displayArgs.Add([string]$arg) | Out-Null
                if ($arg -eq '-ApiKey') { $hideNext = $true }
            }
            Write-Host ("minfocreate args: {0}" -f ($displayArgs -join ' '))
            & $MinfoPath @minfoArgs
        } catch { Write-Host "minfo error: $($_.Exception.Message)"; throw }
    })
    $script:Ps=$ps; $script:Rs=$rs; $script:Async=$ps.BeginInvoke()
    $script:InfoIdx=0; $script:WarnIdx=0
    Start-EncodeTimer
}

function Run-NextPost {
    # Pop and run the next queued post-encode step; finish when the queue empties.
    if (-not $script:PostQueue -or $script:PostQueue.Count -eq 0) { Finish-Encode 'done'; return }
    $next = $script:PostQueue[0]
    $script:PostQueue = @($script:PostQueue | Select-Object -Skip 1)
    $tgt = $script:LastOutput
    if (-not ($tgt -and (Test-Path -LiteralPath $tgt))) { Add-Log "    (post step '$next' skipped: no output file)"; Run-NextPost; return }
    switch ($next) {
        'sample' { Start-Sample -Target $tgt }
        'minfo'  { Start-Minfo  -Target $tgt }
        default  { Run-NextPost }
    }
}


function Start-MediaForgeConsoleTool {
    param(
        [Parameter(Mandatory)][string]$ScriptPath,
        [string[]]$ToolArgs = @(),
        [string]$Name = 'tool'
    )
    if (-not (Test-Path -LiteralPath $ScriptPath -PathType Leaf)) {
        [System.Windows.Forms.MessageBox]::Show("$Name is missing:`n$ScriptPath", 'MediaForge') | Out-Null
        return
    }

    try {
        $pwsh  = (Get-Command pwsh.exe -ErrorAction SilentlyContinue).Source
        $winps = (Get-Command powershell.exe -ErrorAction SilentlyContinue).Source
        $hostExe = if ($pwsh) { $pwsh } else { $winps }
        if (-not $hostExe) { throw 'No pwsh.exe or powershell.exe found.' }

        $argList = @('-NoProfile','-ExecutionPolicy','Bypass','-NoExit','-File', $ScriptPath)
        if ($ToolArgs) { $argList += $ToolArgs }

        Add-Log ("Launching {0}: {1}" -f $Name, (Split-Path $ScriptPath -Leaf))
        Start-Process -FilePath $hostExe -ArgumentList $argList -WorkingDirectory (Split-Path -Parent $ScriptPath) | Out-Null
    }
    catch {
        [System.Windows.Forms.MessageBox]::Show("Failed to launch ${Name}:`n$($_.Exception.Message)", 'MediaForge') | Out-Null
    }
}

function Start-ImdbDumpTool {
    if ($script:Encoding -or $script:Stage -ne 'idle') { return }
    if (-not (Test-EngineAvailable -Path $ImdbDumpPath -Name 'imdbdump.ps1')) { return }

    # imdbdump.ps1 is an interactive console tool, so launch it detached.
    Start-MediaForgeConsoleTool -ScriptPath $ImdbDumpPath -Name 'IMDb dump'
}

function Start-PosterGrabTool {
    if ($script:Encoding -or $script:Stage -ne 'idle') { return }
    if (-not (Test-EngineAvailable -Path $ImdbThumbGrabPath -Name 'imdbthumbgrab.ps1')) { return }

    $id = $txtImdb.Text.Trim()
    $title = $txtName.Text.Trim()
    $year = $txtYear.Text.Trim()

    # If the GUI fields are empty, try to infer title/year from the selected file.
    if (-not $title) {
        $tgt = Get-ToolTarget
        if ($tgt) {
            $base = [System.IO.Path]::GetFileNameWithoutExtension($tgt)
            if ($base -match '^(?<name>.+?)\s*\[(?<year>\d{4})\]$') {
                $title = $matches.name.Trim()
                if (-not $year) { $year = $matches.year }
            } else {
                $title = $base.Trim()
            }
        }
    }

    if (-not ($id -match '^tt\d{6,10}$') -and -not $title) {
        [System.Windows.Forms.MessageBox]::Show('Enter an IMDb ID or movie title/year before downloading a poster.', 'MediaForge') | Out-Null
        return
    }

    $log.Clear(); $script:InfoIdx=0; $script:WarnIdx=0
    $script:Stage = 'poster'
    $script:Encoding = $true
    $script:CancelRequested = $false
    Set-Busy $true
    $progress.Style='Marquee'; $lblStat.Text='  downloading poster...'

    Add-Log '==> Poster download'
    if ($id -match '^tt\d{6,10}$') { Add-Log "    IMDb id: $id" }
    elseif ($title) {
        Add-Log "    Title: $title"
        if ($year -match '^\d{4}$') { Add-Log "    Year: $year" }
    }
    Add-Log '    engine: imdbthumbgrab (OMDb poster download)'

    $rs=[runspacefactory]::CreateRunspace(); $rs.ApartmentState='MTA'; $rs.Open()
    $rs.SessionStateProxy.SetVariable('ImdbThumbGrabPath', $ImdbThumbGrabPath)
    $rs.SessionStateProxy.SetVariable('ImdbId',            $id)
    $rs.SessionStateProxy.SetVariable('MovieTitle',        $title)
    $rs.SessionStateProxy.SetVariable('MovieYear',         $year)
    $ps=[powershell]::Create(); $ps.Runspace=$rs
    [void]$ps.AddScript({
        try {
            $env:MEDIAFORGE_GUI='1'
            $env:MEDIAFORGE_NONINTERACTIVE='1'
            $thumbArgs = @('-NonInteractive')
            if ($ImdbId -match '^tt\d{6,10}$') {
                $thumbArgs += @('-ImdbId', $ImdbId)
            } elseif ($MovieTitle) {
                $thumbArgs += @('-Title', $MovieTitle)
                if ($MovieYear -match '^\d{4}$') { $thumbArgs += @('-Year', $MovieYear) }
            }
            & $ImdbThumbGrabPath @thumbArgs
        } catch { Write-Host "poster error: $($_.Exception.Message)"; throw }
    })
    $script:Ps=$ps; $script:Rs=$rs; $script:Async=$ps.BeginInvoke()
    $script:InfoIdx=0; $script:WarnIdx=0
    Start-EncodeTimer
}

function Start-Tool {
    # Standalone Tools-row run on the File source or the last encode output.
    param([string]$Kind)
    if ($script:Encoding -or $script:Stage -ne 'idle') { return }
    if ($Kind -eq 'sample' -and -not (Test-EngineAvailable -Path $MkvSamplePath -Name 'mkv-sample.ps1')) { return }
    if ($Kind -eq 'minfo'  -and -not (Test-EngineAvailable -Path $MinfoPath -Name 'minfocreate.ps1')) { return }
    $tgt = Get-ToolTarget
    if (-not $tgt) { [System.Windows.Forms.MessageBox]::Show('No target file. Pick a File source (Browse + Scan) or run an encode first.', 'MediaForge') | Out-Null; return }
    $log.Clear(); $script:InfoIdx=0; $script:WarnIdx=0
    $script:Encoding=$true; $script:CancelRequested=$false; Set-Busy $true
    $script:LastOutput = $tgt
    $script:PostQueue  = @($Kind)
    Run-NextPost
}

